WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY discount DESC NULLS FIRST, id ASC) AS rn FROM orders QUALIFY rn = 1) SELECT status, DATE_TRUNC('QUARTER', order_date) AS quarter_start, ROUND(AVG(amount), 2) AS avg_amount, PERCENTILE_APPROX(discount, 0.9) AS discount_p90, SUM(CASE WHEN status = 'PENDING' THEN shipping_fee ELSE 0 END) AS pending_shipping_fee, ROUND(SUM(shipping_fee) / NULLIF(COUNT(CASE WHEN channel = 'mobile' THEN 1 END), 0), 2) AS shipping_fee_per_mobile, SUM(CASE WHEN status = 'PENDING' THEN amount ELSE 0 END) AS pending_amount FROM ranked GROUP BY status, quarter_start HAVING pending_shipping_fee >= 0 ORDER BY avg_amount DESC NULLS LAST
